--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `courses` (
  `course_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `division` smallint NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `professor` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `credits` int NOT NULL,
  `type` enum('major_required','major_elective','major_basic','core_general','balance_general','free_general') COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_grade` smallint DEFAULT NULL,
  `offering_dept` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `belong_dept` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `semester` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_enrollment` int DEFAULT '60',
  `grade_limits` json DEFAULT NULL,
  PRIMARY KEY (`course_id`),
  UNIQUE KEY `uq_course_subject_division` (`subject_code`,`division`),
  KEY `ix_course_subject_code` (`subject_code`),
  KEY `ix_courses_name` (`name`),
  KEY `ix_courses_professor` (`professor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

